namespace ghidra.app.util.viewer.field;



using docking.widgets.fieldpanel.field;
using ghidra.app.nav;
using ghidra.app.plugin.core.symtable;
using ghidra.app.services;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.util;

/**
 * A handler to process Label field clicks
 */
public class LabelFieldMouseHandler : FieldMouseHandlerExtension {

	private static Class<object>[] SUPPORTED_CLASSES =
		new Class<object>[] { typeof(LabelFieldLocation), typeof(MoreLabelFieldLocation) };

	/* @Override */
	public bool fieldElementClicked(object clickedObject, Navigatable sourceNavigatable,
			ProgramLocation location, MouseEvent mouseEvent, ServiceProvider serviceProvider) {

		if (mouseEvent.getClickCount() != 2 || mouseEvent.getButton() != MouseEvent.BUTTON1) {
			return false;
		}

		GoToService goToService = serviceProvider.getService(typeof(GoToService));
		if (goToService == null) {
			Msg.error(this, typeof(GoToService).getSimpleName() + " not installed!");
			return false;
		}

		SymbolTableService service = serviceProvider.getService(typeof(SymbolTableService));
		if (service == null) {
			Msg.error(this, typeof(SymbolTableService).getSimpleName() + " not installed!");
			return false;
		}

		string clickedText = getText(clickedObject);
		if (MoreLabelFieldLocation.MORE_LABELS_STRING.equals(clickedText)) {
			showLabelsDialog(service, location);
			return true;
		}

		if (location is LabelFieldLocation) {
			// Allow double-clicking of any label to show the label dialog.  This allows the user to
			// use the dialog even when the [more] is not showing.
			showLabelsDialog(service, location);
			return true;
		}

		return false;
	}

	private void showLabelsDialog(SymbolTableService service, ProgramLocation location) {

		Address addr = location.getAddress();
		Program program = location.getProgram();
		Listing listing = program.getListing();
		CodeUnit cu = listing.getCodeUnitContaining(addr);
		if (cu != null) {
			service.showSymbols(cu);
			return;
		}
	}

	private string getText(object clickedObject) {
		if (clickedObject is FieldElement) {
			FieldElement fieldElement = (FieldElement) clickedObject;
			return fieldElement.getText();
		}
		return clickedObject.toString();
	}

	/* @Override */
	public Class<object>[] getSupportedProgramLocations() {
		return SUPPORTED_CLASSES;
	}
}
